CREATE DATABASE IF NOT EXISTS student_project_monitoring CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_project_monitoring;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,username VARCHAR(80) UNIQUE NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','teacher','student') NOT NULL,status ENUM('active','inactive') DEFAULT 'active',department VARCHAR(120),student_number VARCHAR(60),course VARCHAR(100),year_level VARCHAR(30),section VARCHAR(50),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects(id INT AUTO_INCREMENT PRIMARY KEY,project_title VARCHAR(255) NOT NULL,description TEXT,teacher_id INT NOT NULL,leader_id INT NULL,status ENUM('Pending','In Progress','Under Review','For Revision','Approved','Completed') DEFAULT 'Pending',progress_percentage TINYINT UNSIGNED DEFAULT 0,deadline DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(teacher_id) REFERENCES users(id),FOREIGN KEY(leader_id) REFERENCES users(id));
CREATE TABLE project_members(project_id INT NOT NULL,student_id INT NOT NULL,member_role ENUM('leader','member') DEFAULT 'member',joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,student_id),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE submissions(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,submitted_by INT NOT NULL,file_name VARCHAR(255),file_path VARCHAR(255),submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(submitted_by) REFERENCES users(id));
CREATE TABLE feedback(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,teacher_id INT NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(teacher_id) REFERENCES users(id));
CREATE TABLE status_history(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30),changed_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES users(id));
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(150),message TEXT,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE activity_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
